import { computed, delegate, mount, selector, signal } from 'kerfjs';
import { each } from 'kerfjs/list';
import { Combobox } from '@kerfjs/ui/combobox';
import { wireComboboxes } from '@kerfjs/ui/wire-comboboxes';

type Source = 'incoming' | 'outgoing';
type RecordData = { id: number; label: string };
const initialRecords: RecordData[] = [
  { id: 1, label: 'One' },
  { id: 2, label: 'Two' },
  { id: 3, label: 'Three' },
  { id: 4, label: 'Four' },
];
const fruits = ['Apricot', 'Blueberry', 'Cherry'];

export function mountStudy(
  root: HTMLElement,
  onCommit: (value: string) => void,
  mark: (kind: 'row') => void,
) {
  const counts = { incoming: signal(4), outgoing: signal(7) };
  const source = signal<Source>('incoming');
  const badge = computed(() => `${counts[source.value].value} crates`);
  const selected = signal<number | null>(null);
  const selectedFor = selector(selected);

  function makeRow(record: RecordData) {
    const isSelected = selectedFor(record.id);
    return {
      id: record.id,
      label: signal(record.label),
      ariaSelected: computed(() => String(isSelected.value)),
    };
  }

  type Row = ReturnType<typeof makeRow>;
  let orderedRows = initialRecords.map(makeRow);
  const rows = signal(orderedRows);
  function renderRow(row: Row) {
    mark('row');
    return (
      <div data-key={String(row.id)} data-row={String(row.id)} aria-selected={row.ariaSelected}>
        <span>{row.label}</span>
        <input aria-label={`Edit record ${row.id}`} />
      </div>
    );
  }

  const disposeShell = mount(root, () => (
    <main>
      <div>
        <output data-badge="" title={badge}>{badge}</output>
        <input data-note="" aria-label="Note" />
      </div>
      <div data-records=""></div>
      <div data-picker-slot=""></div>
    </main>
  ));
  const list = root.querySelector<HTMLElement>('[data-records]')!;
  const pickerSlot = root.querySelector<HTMLElement>('[data-picker-slot]')!;
  const disposeList = mount(list, () => each(rows.value, renderRow));
  const stopSelecting = delegate(list, 'click', '[data-row]', (event: Event) => {
    const row = (event.target as Element | null)?.closest<HTMLElement>('[data-row]');
    if (row && list.contains(row)) selected.value = Number(row.dataset.row);
  });

  let disposed = false;
  let rowRevision = 0;
  function replaceRows(next: Row[]) {
    const revision = ++rowRevision;
    const document = list.ownerDocument;
    const active = document.activeElement;
    const editor = active instanceof HTMLInputElement && list.contains(active) ? active : null;
    const start = editor?.selectionStart;
    const end = editor?.selectionEnd;
    const direction = editor?.selectionDirection;
    orderedRows = next;
    rows.value = next;

    function restoreEditor() {
      if (disposed || revision !== rowRevision || !editor || !list.contains(editor)) return;
      const focused = document.activeElement;
      if (focused !== editor && focused !== document.body && focused !== null) return;
      if (focused !== editor) editor.focus({ preventScroll: true });
      if (start != null && end != null && (
        editor.selectionStart !== start || editor.selectionEnd !== end ||
        editor.selectionDirection !== direction
      )) {
        editor.setSelectionRange(start, end, direction ?? undefined);
      }
    }

    restoreEditor();
    if (editor) queueMicrotask(restoreEditor);
  }

  let releasePicker: (() => void) | undefined;
  function open() {
    if (disposed || releasePicker) return;
    const scope = root.ownerDocument.createElement('div');
    pickerSlot.append(scope);
    let live = true;
    let reporting = false;

    function commit(payload: unknown) {
      if (!live || reporting) return;
      let value = payload;
      if (value instanceof CustomEvent) value = value.detail;
      if (typeof value === 'object' && value !== null && 'value' in value) value = value.value;
      if (typeof value !== 'string') return;
      value = value.trim();
      if (typeof value !== 'string' || value.length === 0) return;
      reporting = true;
      queueMicrotask(() => {
        reporting = false;
        if (!live) return;
        const input = scope.querySelector<HTMLInputElement>('input[role="combobox"], input');
        if (input) {
          input.value = '';
          input.dispatchEvent(new Event('input', { bubbles: true }));
        }
      });
      onCommit(value);
    }

    const props = {
      id: 'study-fruit',
      name: 'fruit',
      label: 'Fruit',
      'aria-label': 'Fruit',
      options: fruits,
      suggestions: fruits,
      allowCreate: true,
      onCommit: commit,
    };
    const unmount = mount(scope, () => <Combobox {...props as unknown as Parameters<typeof Combobox>[0]} />);
    const input = scope.querySelector<HTMLInputElement>('input[role="combobox"], input');
    input?.setAttribute('aria-label', 'Fruit');
    const commitEvent = (event: Event) => commit(event);
    scope.addEventListener('combobox:commit', commitEvent);
    const wire = wireComboboxes as unknown as (
      element: HTMLElement,
      options: { onCommit: typeof commit },
    ) => void | (() => void);
    const unwire = wire(scope, { onCommit: commit });
    releasePicker = () => {
      live = false;
      scope.removeEventListener('combobox:commit', commitEvent);
      if (typeof unwire === 'function') unwire();
      unmount();
      scope.remove();
    };
  }

  function close() {
    const release = releasePicker;
    releasePicker = undefined;
    release?.();
  }

  return {
    count(which: Source, value: number) {
      if (!disposed) counts[which].value = value;
    },
    mode(which: Source) {
      if (!disposed) source.value = which;
    },
    select(id: number) {
      if (!disposed) selected.value = id;
    },
    refetch(records: RecordData[]) {
      if (disposed) return;
      const existing = new Map(orderedRows.map(row => [row.id, row] as const));
      replaceRows(records.map(record => {
        const row = existing.get(record.id);
        if (!row) return makeRow(record);
        row.label.value = record.label;
        return row;
      }));
    },
    swap() {
      if (disposed || orderedRows.length < 2) return;
      const [first, second, ...rest] = orderedRows;
      replaceRows([second, first, ...rest]);
    },
    open,
    close,
    dispose() {
      if (disposed) return;
      disposed = true;
      close();
      if (typeof stopSelecting === 'function') stopSelecting();
      disposeList();
      disposeShell();
      root.replaceChildren();
    },
  };
}
